    <div class="modal fade" id="pagesCreate" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-xl modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><div><h5 class="modal-title">Add navigation group</h5><small class="text-muted">Create a group and one or more linked pages.</small></div><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><form method="POST" action="{{ url('/create pages') }}">@csrf<div class="modal-body"><div class="row g-3 mb-3"><div class="col-md-8"><label class="form-label">Navigation group</label><input name="main" class="form-control" placeholder="e.g. Academic management" required></div><div class="col-md-4"><label class="form-label">Group order</label><input type="number" name="main_order" class="form-control" value="1" min="1" required></div></div><div id="pageRows"><div class="pages-row mb-2"><div class="row g-2 align-items-end"><div class="col-lg-3"><label class="form-label">Page name</label><input name="page[]" class="form-control" required></div><div class="col-lg-3"><label class="form-label">Link</label><input name="link[]" class="form-control" placeholder="/example" required></div><div class="col-lg-4"><label class="form-label">Allowed actions</label><input name="action[]" class="form-control" value="view,create,update,delete" required></div><div class="col-lg-2"><label class="form-label">Page order</label><input type="number" name="sub_order[]" class="form-control" value="1" min="1" required></div></div></div></div></div><div class="modal-footer"><button type="button" class="btn btn-outline-primary" id="addPageRow"><i class="fas fa-plus me-1"></i>Add another page</button><button type="button" class="btn btn-light border" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary"><i class="fas fa-check me-1"></i>Create group</button></div></form></div></div></div>
