<script>
document.addEventListener('DOMContentLoaded',function(){const list=document.getElementById('pageRows'),add=document.getElementById('addPageRow');if(!list||!add)return;add.addEventListener('click',function(){const row=list.querySelector('.pages-row').cloneNode(true);row.querySelectorAll('input').forEach(function(input){if(input.name==='action[]')input.value='view,create,update,delete';else if(input.name==='sub_order[]')input.value=list.querySelectorAll('.pages-row').length+1;else input.value='';});list.appendChild(row);});});
</script>
